// Load last run timestamp from workflow static data.
// Immediately advance the saved timestamp to now — this way,
// even if the workflow fails mid-run, the next execution will
// not reprocess the same window (preventing duplicate SD tickets).
const staticData = $getWorkflowStaticData('global');

const queryFrom = staticData.lastRunTimestamp
  ? staticData.lastRunTimestamp
  : new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(); // default: last 24h on first run

// Advance the saved timestamp before we do any work
staticData.lastRunTimestamp = new Date().toISOString();

return [{ json: { queryFrom } }];

// Parse the PLANE API response and map issues to the service desk schema.
// Filter out issues that were already synced (external_source === 'servicedesk').
const body = $input.first().json;
const issues = body.results || body.issues || (Array.isArray(body) ? body : []);

if (!issues.length) return [];

// Skip issues already linked to the service desk
const pending = issues.filter(
  issue => issue.external_source !== 'servicedesk'
);

if (!pending.length) return [];

return pending.map(issue => ({
  json: {
    // Service desk payload
    source: 'plane',
    plane_issue_id: issue.id,
    plane_identifier: issue.sequence_id || issue.name,
    title: issue.name || issue.title || '(no title)',
    description: (issue.description_stripped || issue.description || '').substring(0, 2000),
    priority: issue.priority || 'none',
    state: issue.state_detail?.name || issue.state || '',
    state_group: issue.state_detail?.group || '',
    labels: (issue.label_details || []).map(l => l.name).concat(
      (issue.labels || []).filter(l => typeof l === 'string')
    ),
    assignees: issue.assignees || [],
    project_id: issue.project,
    workspace: $env.PLANE_WORKSPACE_SLUG,
    url: `${$env.PLANE_URL}/${$env.PLANE_WORKSPACE_SLUG}/projects/${issue.project}/issues/${issue.id}/`,
    created_at: issue.created_at,
    updated_at: issue.updated_at,
    // Internal fields for the write-back step
    _plane_project_id: issue.project,
    _plane_issue_id: issue.id
  }
}));
